import{_ as r,C as a,c as n,o as i,a3 as t,G as s}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Generate leads from visitors","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/crm/acquire-leads/lead-generation.md","filePath":"master/sales/crm/acquire-leads/lead-generation.md","lastUpdated":1793789158000}'),l={name:"master/sales/crm/acquire-leads/lead-generation.md"};function g(h,e,d,c,u,m){const o=a("ImagePopup");return i(),n("div",null,[e[0]||(e[0]=t('<h1 id="generate-leads-from-visitors" tabindex="-1">Generate leads from visitors <a class="header-anchor" href="#generate-leads-from-visitors" aria-label="Permalink to &quot;Generate leads from visitors&quot;">​</a></h1><p>Visitor rules create leads for you when people browse your website. You decide which visitors count, such as those from one country or those who open one page. Aureus then adds a lead with the tags, priority, team and salesperson you chose.</p><blockquote><p><strong>In simple words:</strong> A rule watches your website and makes a lead when a visitor matches it.</p></blockquote><p>This feature needs the Website app to be installed. Without it, the switch in the settings stays off.</p><div class="info custom-block"><p class="custom-block-title">About the example</p><p>Sharma Textiles wants more enquiries from India. You create a rule named <code>Textile page visitors</code>. It makes a lead for each visitor from India who opens a page with <code>/textile</code> in its address.</p></div><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>Turn the feature on first.</p><ol><li>Go to <code>CRM → Settings → Manage Lead Generation</code>.</li><li>Switch on <strong>Visitors to Leads</strong>.</li><li>Click <strong>Save changes</strong>.</li></ol>',8)),s(o,{src:"/images1/crm/lead-generation-settings.png",alt:"Manage Lead Generation settings with Visitors to Leads switched on and the Manage Rules button"}),e[1]||(e[1]=t('<p>Once the switch is on, a line tells you how many rules are active. If there are none, it warns you that visits will not create leads until you add a rule.</p><ul><li><strong>Manage Rules</strong> opens the list of rules.</li><li><strong>Create Leads for Existing Visitors</strong> applies the active rules to pages that visitors already opened. It shows only when at least one rule is active and some visitors have no lead. Aureus asks you to confirm, then reports how many leads it created.</li></ul><h2 id="the-rules-list" tabindex="-1">The rules list <a class="header-anchor" href="#the-rules-list" aria-label="Permalink to &quot;The rules list&quot;">​</a></h2><p>Open <code>CRM → Configuration → Visitors to Leads Rules</code>. The page appears only when the feature is on.</p><h3 id="columns" tabindex="-1">Columns <a class="header-anchor" href="#columns" aria-label="Permalink to &quot;Columns&quot;">​</a></h3><p>The list shows <strong>Rule Name</strong>, <strong>URL Expression</strong>, <strong>Countries</strong>, <strong>Type</strong>, <strong>Sales Team</strong>, <strong>Salesperson</strong>, <strong>Leads</strong>, <strong>Opportunities</strong> and <strong>Active</strong>.</p><ul><li><strong>URL Expression</strong> shows <strong>Whole website</strong> when the rule has no expression.</li><li><strong>Countries</strong> shows <strong>All countries</strong> when the rule has none.</li><li><strong>Leads</strong> and <strong>Opportunities</strong> count what the rule created.</li><li>Click the <strong>Active</strong> switch to turn a rule on or off.</li></ul><h3 id="search-filter-and-order" tabindex="-1">Search, filter and order <a class="header-anchor" href="#search-filter-and-order" aria-label="Permalink to &quot;Search, filter and order&quot;">​</a></h3><ul><li>Type in the search box to find a rule by name.</li><li>Use the <strong>Active</strong> filter to show active or inactive rules.</li><li>Drag a row to change the order. The first matching rule wins when a visitor fits more than one.</li><li>Row actions are <strong>View</strong>, <strong>Edit</strong> and <strong>Delete</strong>. Bulk actions let you export or delete ticked rules.</li></ul><h2 id="create-a-rule" tabindex="-1">Create a rule <a class="header-anchor" href="#create-a-rule" aria-label="Permalink to &quot;Create a rule&quot;">​</a></h2><ol><li>Go to <code>CRM → Configuration → Visitors to Leads Rules</code>.</li><li>Click <strong>New Visitors to Leads Rule</strong>.</li><li>Fill in the form.</li><li>Click <strong>Create</strong>. Use <strong>Create &amp; create another</strong> to save and open an empty form.</li></ol>',11)),s(o,{src:"/images1/crm/visitor-rule-form.png",alt:"Create Visitors to Leads Rule form filled in for textile page visitors from India"}),e[2]||(e[2]=t('<h3 id="rule" tabindex="-1">Rule <a class="header-anchor" href="#rule" aria-label="Permalink to &quot;Rule&quot;">​</a></h3><ul><li><strong><em>Rule Name:</em></strong> A clear name for the rule. Required, up to 255 characters. The hint reads <strong>e.g. US Visitors</strong>.</li></ul><p><strong>Example:</strong> <code>Textile page visitors</code>.</p><h3 id="website-traffic-conditions" tabindex="-1">Website Traffic Conditions <a class="header-anchor" href="#website-traffic-conditions" aria-label="Permalink to &quot;Website Traffic Conditions&quot;">​</a></h3><ul><li><strong><em>Countries:</em></strong> Only visitors from these countries match. Aureus finds the country from the visitor&#39;s IP address. Leave it empty for all countries.</li><li><strong><em>States:</em></strong> Only visitors from these states match. It shows after you pick a country. Aureus knows the state only for logged-in customers, from their address. Leave it empty for all states.</li><li><strong><em>URL Expression:</em></strong> The pages that count. Enter a regular expression on the page path. Leave it empty for the whole website. Enter <code>/</code> for the home page only. Enter <code>/pricing|/shop</code> for pages that contain <code>/pricing</code> or <code>/shop</code>. An invalid expression is rejected with the message <strong>Enter a valid expression.</strong></li></ul><p><strong>Example:</strong> Pick <strong>India</strong> as <strong>Countries</strong>. Enter <code>/textile</code> as <strong>URL Expression</strong>.</p><h3 id="contact-filter" tabindex="-1">Contact Filter <a class="header-anchor" href="#contact-filter" aria-label="Permalink to &quot;Contact Filter&quot;">​</a></h3><p>This section shows only when <strong>Data Tracking</strong> is <strong>Companies and their contacts</strong>. A note reminds you to check whether you must follow data protection law (GDPR) when you store personal data.</p><ul><li><strong><em>Number of Contacts:</em></strong> <strong>1 contact</strong> to <strong>5 contacts</strong>. It starts at <strong>1 contact</strong>. Required.</li><li><strong><em>Filter Contacts On:</em></strong> Choose <strong>Role</strong> or <strong>Seniority</strong>. It starts as <strong>Role</strong>. Required.</li><li><strong><em>Preferred Role:</em></strong> The main role you look for. It shows for <strong>Role</strong>. Pick one, or type a new name to add it.</li><li><strong><em>Other Roles:</em></strong> More roles you accept. It shows after you pick a <strong>Preferred Role</strong>.</li><li><strong><em>Seniority:</em></strong> The level you look for. It shows for <strong>Seniority</strong>. Pick one, or type a new name to add it.</li></ul><h3 id="lead-data" tabindex="-1">Lead Data <a class="header-anchor" href="#lead-data" aria-label="Permalink to &quot;Lead Data&quot;">​</a></h3><p>The title of this section is <strong>Opportunity Data</strong> when the <strong>Type</strong> is <strong>Opportunity</strong>.</p><ul><li><strong><em>Tags:</em></strong> Tags added to each lead the rule creates. You can pick many. See <a href="./../configuration/tags.html">Tags</a>.</li><li><strong><em>Suffix:</em></strong> Text added to the end of the lead name. For example, <code>Website visitor #12 (India) - Pricing</code>.</li><li><strong><em>Priority:</em></strong> The priority of the new lead. It starts as <strong>Low</strong>.</li><li><strong><em>Sales Team:</em></strong> The team that receives the lead.</li><li><strong><em>Company:</em></strong> The company the lead belongs to. Leave it empty to use the customer&#39;s company, or the first active company.</li><li><strong><em>Salesperson:</em></strong> The owner of the lead. The list depends on the <strong>Company</strong> you chose.</li></ul><p><strong>Example:</strong> Add the tag <strong>Software</strong>. Set <strong>Suffix</strong> to <code>Textile page</code>, <strong>Priority</strong> to <strong>High</strong>, and <strong>Sales Team</strong> to <strong>Sales</strong>.</p><h3 id="settings-1" tabindex="-1">Settings <a class="header-anchor" href="#settings-1" aria-label="Permalink to &quot;Settings&quot;">​</a></h3><ul><li><strong><em>Active:</em></strong> Turns the rule on. It starts on.</li><li><strong><em>Data Tracking:</em></strong> Choose <strong>Companies</strong> or <strong>Companies and their contacts</strong>. It starts as <strong>Companies</strong>. Required.</li><li><strong><em>Type:</em></strong> Choose <strong>Lead</strong> or <strong>Opportunity</strong>. It shows only when <strong>Lead Qualification</strong> is on. Then it starts as <strong>Lead</strong>. Required.</li></ul><h3 id="lead-generation-conditions" tabindex="-1">Lead Generation Conditions <a class="header-anchor" href="#lead-generation-conditions" aria-label="Permalink to &quot;Lead Generation Conditions&quot;">​</a></h3><p>The title is <strong>Opportunity Generation Conditions</strong> when the <strong>Type</strong> is <strong>Opportunity</strong>.</p><ul><li><strong><em>Industries:</em></strong> The industries you target. Pick many, or type a name to add a new industry.</li><li><strong><em>Filter on Size:</em></strong> Switch on to limit by company size. It starts on.</li><li><strong><em>Company Size From:</em></strong> The smallest number of employees. It starts at 0. Required when the size filter is on.</li><li><strong><em>Company Size To:</em></strong> The largest number of employees, shown with the unit <strong>employees</strong>. It starts at 1000 and cannot be lower than <strong>Company Size From</strong>. Required when the size filter is on.</li></ul><h2 id="the-rule-page" tabindex="-1">The rule page <a class="header-anchor" href="#the-rule-page" aria-label="Permalink to &quot;The rule page&quot;">​</a></h2><p>A saved rule opens with three tabs: <strong>View</strong>, <strong>Edit</strong> and <strong>Generated Leads</strong>. A number on <strong>Generated Leads</strong> shows how many records the rule created. The tab lists their <strong>Name</strong>, <strong>Country</strong>, <strong>Stage</strong> and <strong>Created</strong> date.</p><h2 id="behind-the-scenes" tabindex="-1">Behind the scenes <a class="header-anchor" href="#behind-the-scenes" aria-label="Permalink to &quot;Behind the scenes&quot;">​</a></h2><ul><li>Aureus watches each visitor page view. If an active rule matches the page and the place, it queues the visit and creates the lead.</li><li>A visitor gets one lead only. If more than one rule matches, the first rule in the list order is used.</li><li>The lead name is <code>Website visitor #&lt;number&gt;</code>, with the country in brackets when known. For a logged-in customer it is <code>Website visitor: &lt;customer name&gt;</code>. Your <strong>Suffix</strong> follows after a hyphen.</li><li>The lead copies the customer&#39;s name, email, phone and address when the visitor is a known customer. <strong>Referred By</strong> shows <strong>Website Visitor</strong>.</li><li>The <strong>Notes</strong> field lists the rule, IP address, country, time zone, language, landing page and first visit date. The lead page also shows the <strong>IP Address</strong>.</li><li>The lead is created as a <strong>Lead</strong> only when the rule <strong>Type</strong> is <strong>Lead</strong> and <strong>Lead Qualification</strong> is on. Otherwise it is an opportunity.</li><li>Leads from a rule appear in <code>CRM → Leads → Leads</code> like any other lead.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Test a rule with a narrow <strong>URL Expression</strong> first. A broad rule can create many leads in a day.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./create-lead.html">Create a lead</a></li><li><a href="./convert-lead.html">Convert a lead</a></li><li><a href="./../configuration/tags.html">Tags</a></li><li><a href="./../configuration/settings.html">CRM settings</a></li></ul>',25))])}const w=r(l,[["render",g]]);export{f as __pageData,w as default};
